// Legal Dictionary Terms Database
// 500+ essential legal terms for Indian lawyers across 17 categories

class LegalTerm {
  final String term;
  final String category;
  final String meaning;
  final String usage;
  final String section;
  const LegalTerm({required this.term, required this.category, required this.meaning, this.usage = '', this.section = ''});
}

const List<LegalTerm> legalTermsData = [
  // ═══ LATIN MAXIMS ═══
  LegalTerm(term: 'Audi Alteram Partem', category: 'Latin', meaning: 'Hear the other side. No person should be condemned unheard.', usage: 'A fundamental rule of natural justice — courts must give both parties a chance to be heard before passing orders.', section: 'Article 14, 21 Constitution'),
  LegalTerm(term: 'Res Judicata', category: 'Latin', meaning: 'A matter already judged. A decided case cannot be re-litigated between the same parties on the same issue.', usage: 'The defendant raised a plea of res judicata under Section 11 CPC, arguing this issue was already decided in a prior suit.', section: 'Section 11 CPC'),
  LegalTerm(term: 'Res Ipsa Loquitur', category: 'Latin', meaning: 'The thing speaks for itself. Negligence is inferred from the very nature of the accident.', usage: 'When a surgical sponge is left inside a patient, res ipsa loquitur applies — the negligence is self-evident.'),
  LegalTerm(term: 'Actus Reus', category: 'Latin', meaning: 'Guilty act. The physical element of a crime.', usage: 'For a conviction of murder, prosecution must prove both actus reus (the killing) and mens rea (the intention).', section: 'BNS General Principles'),
  LegalTerm(term: 'Mens Rea', category: 'Latin', meaning: 'Guilty mind. The mental element or criminal intent required for a crime.', usage: 'The accused had no mens rea since the death was purely accidental, not intentional or reckless.', section: 'BNS General Principles'),
  LegalTerm(term: 'Habeas Corpus', category: 'Latin', meaning: 'Produce the body. A writ directing a person detaining another to produce them before the court.', usage: 'A habeas corpus petition was filed in High Court challenging the illegal detention of the accused beyond 24 hours.', section: 'Article 32, 226 Constitution'),
  LegalTerm(term: 'Mandamus', category: 'Latin', meaning: 'We command. A writ ordering a public authority to perform its duty.', usage: 'Mandamus was issued directing the municipality to repair the road, being a public duty they were bound to perform.', section: 'Article 32, 226 Constitution'),
  LegalTerm(term: 'Certiorari', category: 'Latin', meaning: 'To be certified. A writ by a higher court to review and quash the decision of a lower court or tribunal.', usage: 'The High Court issued certiorari quashing the tribunal order as it was passed without jurisdiction.', section: 'Article 226, 227 Constitution'),
  LegalTerm(term: 'Quo Warranto', category: 'Latin', meaning: 'By what authority? A writ challenging the legal authority of a person holding public office.', usage: 'Quo warranto was filed questioning the appointment of the Municipal Commissioner without following statutory procedure.', section: 'Article 226 Constitution'),
  LegalTerm(term: 'Prohibition', category: 'Latin', meaning: 'A writ issued by a higher court preventing a lower court from exceeding its jurisdiction.', usage: 'Writ of prohibition was issued to prevent the civil court from trying a matter exclusively within revenue court jurisdiction.', section: 'Article 226 Constitution'),
  LegalTerm(term: 'Caveat Emptor', category: 'Latin', meaning: 'Let the buyer beware. The buyer takes the risk regarding quality of the goods purchased.', usage: 'Under caveat emptor, the buyer who failed to inspect the property before purchase cannot later claim hidden defects.', section: 'Section 16 Sale of Goods Act'),
  LegalTerm(term: 'Damnum Sine Injuria', category: 'Latin', meaning: 'Damage without legal injury. Loss suffered without violation of any legal right — not actionable.', usage: 'Opening a competing shop causing loss to a rival is damnum sine injuria — no legal right is infringed.'),
  LegalTerm(term: 'Injuria Sine Damno', category: 'Latin', meaning: 'Legal injury without actual damage. Violation of a legal right even without loss — actionable.', usage: 'Refusing a registered voter entry to the polling booth is injuria sine damno — legal right violated even if no monetary damage.'),
  LegalTerm(term: 'Volenti Non Fit Injuria', category: 'Latin', meaning: 'A willing person suffers no injury. Consent to risk negates a claim for injury.', usage: 'A boxer cannot sue for injuries sustained during a match — volenti non fit injuria applies.'),
  LegalTerm(term: 'Nemo Debet Bis Vexari', category: 'Latin', meaning: 'No person should be tried or punished twice for the same offence. Double jeopardy.', usage: 'The accused was acquitted once; prosecuting again on the same facts violates the principle of double jeopardy.', section: 'Article 20(2) Constitution / Sec 337 BNSS'),
  LegalTerm(term: 'Ubi Jus Ibi Remedium', category: 'Latin', meaning: 'Where there is a right, there is a remedy.', usage: 'The court cannot refuse relief merely because no specific remedy is mentioned in statute — ubi jus ibi remedium applies.'),
  LegalTerm(term: 'Ignorantia Juris Non Excusat', category: 'Latin', meaning: 'Ignorance of law is no excuse. Every person is presumed to know the law.', usage: 'The accused cannot escape liability by claiming he did not know that carrying a knife in public was illegal.'),
  LegalTerm(term: 'De Facto', category: 'Latin', meaning: 'In fact. Existing in reality, whether legally recognized or not.', usage: 'He was the de facto guardian of the minor, though no formal guardianship order was passed.'),
  LegalTerm(term: 'De Jure', category: 'Latin', meaning: 'By law. Legally recognized, whether or not it exists in practice.', usage: 'She is the de jure owner per the title deed, though the property is in de facto possession of the tenant.'),
  LegalTerm(term: 'Prima Facie', category: 'Latin', meaning: 'At first sight. Evidence sufficient to establish a fact unless rebutted.', usage: 'The prosecution established a prima facie case for framing charges against the accused.', section: 'Sec 232 BNSS (Charge)'),
  LegalTerm(term: 'Obiter Dictum', category: 'Latin', meaning: 'Said in passing. Observations by a judge not essential to the decision — not binding precedent.', usage: 'The Supreme Court\'s remark on social media regulation was merely obiter dictum, not the ratio decidendi.'),
  LegalTerm(term: 'Ratio Decidendi', category: 'Latin', meaning: 'The reason for deciding. The legal principle on which a judgment is based — binding as precedent.', usage: 'The ratio decidendi of Maneka Gandhi v. Union of India is that Article 21 includes the right to live with dignity.'),
  LegalTerm(term: 'Stare Decisis', category: 'Latin', meaning: 'Stand by what has been decided. Courts should follow precedent.', usage: 'Following the doctrine of stare decisis, the High Court is bound by Supreme Court judgments on the same point of law.'),
  LegalTerm(term: 'Locus Standi', category: 'Latin', meaning: 'Right to stand. The legal capacity to bring a case before the court.', usage: 'A stranger to a contract has no locus standi to challenge its terms in court.'),
  LegalTerm(term: 'Inter Alia', category: 'Latin', meaning: 'Among other things.', usage: 'The petition raised, inter alia, the violation of Article 14 and Article 21 of the Constitution.'),
  LegalTerm(term: 'Mala Fide', category: 'Latin', meaning: 'In bad faith. Done with dishonest or fraudulent intent.', usage: 'The transfer order was passed mala fide, as a punishment for filing an RTI application.'),
  LegalTerm(term: 'Bona Fide', category: 'Latin', meaning: 'In good faith. Genuine and honest.', usage: 'The landlord requires the premises for bona fide personal use under the Rent Control Act.'),
  LegalTerm(term: 'Ultra Vires', category: 'Latin', meaning: 'Beyond the powers. An act done beyond the legal authority of the person or body doing it.', usage: 'The municipal notification was struck down as ultra vires the parent statute.'),
  LegalTerm(term: 'Intra Vires', category: 'Latin', meaning: 'Within the powers. An act done within legal authority.', usage: 'The regulation was held intra vires as Parliament had expressly delegated this power.'),
  LegalTerm(term: 'Sub Judice', category: 'Latin', meaning: 'Under judicial consideration. A case currently being heard.', usage: 'The matter is sub judice before the Supreme Court; no comment should be made that prejudices the case.', section: 'Sec 3 Contempt of Courts Act'),
  LegalTerm(term: 'Suo Motu', category: 'Latin', meaning: 'On its own motion. When a court takes action without a petition or complaint.', usage: 'The High Court took suo motu cognizance of the pollution in the river based on newspaper reports.'),
  LegalTerm(term: 'Ad Interim', category: 'Latin', meaning: 'In the meantime. A temporary order pending final hearing.', usage: 'The court granted ad interim injunction restraining the defendant from alienating the property.'),
  LegalTerm(term: 'Ex Parte', category: 'Latin', meaning: 'From one side only. A hearing or order made without the other party being present.', usage: 'An ex parte decree was passed as the defendant failed to appear despite due service of summons.', section: 'Order 9 Rule 6 CPC'),
  LegalTerm(term: 'Ad Hoc', category: 'Latin', meaning: 'For this purpose. Temporary or formed for a specific task.', usage: 'An ad hoc committee was constituted to investigate the allegations against the officer.'),
  LegalTerm(term: 'Amicus Curiae', category: 'Latin', meaning: 'Friend of the court. A person appointed by the court to assist with legal arguments in public interest cases.', usage: 'The Supreme Court appointed a senior advocate as amicus curiae to assist in the PIL.'),
  LegalTerm(term: 'Pro Bono', category: 'Latin', meaning: 'For the public good. Legal services rendered free of charge.', usage: 'The advocate appeared pro bono for the indigent accused who could not afford legal representation.'),
  LegalTerm(term: 'Ipso Facto', category: 'Latin', meaning: 'By the fact itself. As an inevitable consequence.', usage: 'Conviction under BNS Section 103 ipso facto disqualifies a person from holding public office.'),
  LegalTerm(term: 'Mutatis Mutandis', category: 'Latin', meaning: 'With necessary changes. Applied with appropriate modifications.', usage: 'The rules applicable to civil suits shall apply mutatis mutandis to appeals.'),
