  LegalTerm(term: 'Revision', category: 'Legal English', meaning: 'Supervisory jurisdiction of a higher court to correct errors of jurisdiction by lower courts.', usage: 'A revision petition was filed under Sec 115 CPC before the High Court.', section: 'Sec 115 CPC / Sec 442 BNSS'),
